def threeSum(nums):
    nums.sort()
    res, n = [], len(nums)
    for i in range(n - 2):
        if nums[i] > 0:
            break                       # 最小数已 > 0，后面无解
        if i > 0 and nums[i] == nums[i - 1]:
            continue                    # 跳过重复的第一个数
        l, r = i + 1, n - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                res.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l + 1]:
                    l += 1              # 跳过重复的第二个数
                while l < r and nums[r] == nums[r - 1]:
                    r -= 1              # 跳过重复的第三个数
                l += 1
                r -= 1
    return res

solution.python_alt:
def threeSum(nums):
    nums.sort()
    res = set()
    for i in range(len(nums) - 2):
        if nums[i] > 0:
            break
        seen = set()                    # 处理 i 时记录出现过的数
        target = -nums[i]
        for j in range(i + 1, len(nums)):
            if target - nums[j] in seen:
                res.add((nums[i], target - nums[j], nums[j]))
            seen.add(nums[j])
    return [list(t) for t in res]
